export const updateListingBodyCityMax = 100;

export const updateListingBodyUnitPriceMax = 32;


export const updateListingBodyUnitPriceRegExp = new RegExp('^[0-9]+(\\.[0-9]+)?$');

export const updateListingBodyImageUrlsItemMax = 2000;

export const updateListingBodyImageUrlsMax = 6;

export const updateListingBodyContactPhoneMax = 30;



export const UpdateListingBody = zod.object({
  "title": zod.string().min(updateListingBodyTitleMin),
  "description": zod.string().min(updateListingBodyDescriptionMin),
  "category": zod.string(),
  "categoryId": zod.string().optional(),
  "area": zod.string(),
  "city": zod.string().max(updateListingBodyCityMax).optional(),
  "attributes": zod.record(zod.string(), zod.unknown()).optional(),
  "unitPrice": zod.string().min(1).max(updateListingBodyUnitPriceMax).regex(updateListingBodyUnitPriceRegExp).nullable(),
  "pricingMode": zod.enum(['FIXED', 'NEGOTIABLE', 'OPEN_TO_OFFERS']).optional(),
  "priceRepresentation": zod.enum(['FIXED', 'NEGOTIABLE', 'OPEN_TO_OFFERS', 'STARTING_FROM', 'QUOTE_REQUIRED']).optional().describe('What the price means. STARTING_FROM (a starting amount) and QUOTE_REQUIRED (no price; the seller quotes) are stored as pricingMode OPEN_TO_OFFERS and are never bought directly. Only FIXED is purchasable without an agreement; every representation accepts buyer proposals.'),
  "availableQuantity": zod.int().min(1).nullish(),
  "inventoryMode": zod.enum(['LIMITED', 'UNLIMITED']),
  "fulfilmentType": zod.enum(['PICKUP', 'DELIVERY', 'DIGITAL', 'SERVICE']),
  "imageUrl": zod.string(),
  "imageUrls": zod.array(zod.string().max(updateListingBodyImageUrlsItemMax)).max(updateListingBodyImageUrlsMax).optional(),
  "contactPhone": zod.string().max(updateListingBodyContactPhoneMax).nullish(),
  "negotiable": zod.boolean().optional()
})

export const updateListingResponseSponsoredTokenMax = 1024;

export const updateListingResponseRecommendationReasonsItemMax = 120;

export const updateListingResponseRecommendationReasonsMax = 6;

export const updateListingResponsePaymentMethodsMax = 2;

export const updateListingResponseAvailableQuantityMin = 0;

export const updateListingResponseImageUrlsItemMax = 2000;

export const updateListingResponseImageUrlsMax = 6;

export const updateListingResponseContactPhoneMax = 30;



export const UpdateListingResponse = zod.object({
  "id": zod.string(),
  "title": zod.string(),
  "description": zod.string(),
  "category": zod.string(),
  "categoryId": zod.string().optional(),
  "isSponsored": zod.boolean().optional().describe('Set only by the server for a paid placement; always rendered with a visible «إعلان ممول» label.'),
  "sponsoredTier": zod.enum(['STANDARD', 'VIP']).optional().describe('Paid tier of a sponsored slot; VIP is shown together with «ممول» and never means a verified seller.'),
  "sponsoredToken": zod.string().max(updateListingResponseSponsoredTokenMax).optional().describe('Opaque signed attribution token for a delivered paid card (no personal data); the server alone decides any charge.'),
  "recommendationReasons": zod.array(zod.string().max(updateListingResponseRecommendationReasonsItemMax)).max(updateListingResponseRecommendationReasonsMax).optional().describe('Recommendation and buyer-ranking surfaces only; each reason is a deterministic signal that matched.'),
  "area": zod.string(),
  "city": zod.string().optional(),
  "attributes": zod.record(zod.string(), zod.unknown()).optional(),
  "paymentMethods": zod.array(zod.enum(['CASH_DIRECT', 'CARD'])).max(updateListingResponsePaymentMethodsMax).optional(),
  "unitPrice": zod.string().nullable(),
  "pricingMode": zod.enum(['FIXED', 'NEGOTIABLE', 'OPEN_TO_OFFERS']),
  "priceRepresentation": zod.enum(['FIXED', 'NEGOTIABLE', 'OPEN_TO_OFFERS', 'STARTING_FROM', 'QUOTE_REQUIRED']).optional().describe('What the price means. STARTING_FROM (a starting amount) and QUOTE_REQUIRED (no price; the seller quotes) are stored as pricingMode OPEN_TO_OFFERS and are never bought directly. Only FIXED is purchasable without an agreement; every representation accepts buyer proposals.'),
  "currency": zod.string(),
  "availableQuantity": zod.int().min(updateListingResponseAvailableQuantityMin).nullable(),
  "reservedQuantity": zod.int(),
  "inventoryMode": zod.enum(['LIMITED', 'UNLIMITED']),
  "fulfilmentType": zod.enum(['PICKUP', 'DELIVERY', 'DIGITAL', 'SERVICE']),
  "sellerName": zod.string(),
  "sellerId": zod.string().optional(),
  "sellerAvatarObjectPath": zod.string().nullish(),
  "rating": zod.number(),
  "reviewCount": zod.int().optional(),
  "imageUrl": zod.string(),
  "imageUrls": zod.array(zod.string().max(updateListingResponseImageUrlsItemMax)).max(updateListingResponseImageUrlsMax).optional(),
  "contactPhone": zod.string().max(updateListingResponseContactPhoneMax).nullable(),
  "negotiable": zod.boolean().optional().describe('A buyer may propose a price on this listing (true for every listing with a known price representation). An agreed price is private to that buyer; the public price never changes.'),
  "status": zod.enum(['DRAFT', 'PUBLISHED', 'PAUSED', 'ARCHIVED']),
  "createdAt": zod.string().optional()
})


